/**
 * Branded ID types.
 *
 * Every aggregate's primary key is `BIGINT ... GENERATED ALWAYS AS IDENTITY`
 * (PRD §9.0), so IDs are numeric at the database level. We brand them so that a
 * `WorkOrderId` can never be passed where a `VehicleId` is expected, even though
 * both are `number` at runtime. Branding is compile-time only: the `__brand`
 * property never exists at runtime.
 *
 * Business-visible running numbers (WO-0142, B 1234 ABC, TY-0001, TR-0001, …)
 * are plain strings generated by `@bmi/config` and are NOT branded here — they
 * are display identifiers, not foreign keys.
 */

declare const brand: unique symbol;

/** Attach a compile-time-only brand `B` to a base type `T`. */
export type Brand<T, B extends string> = T & { readonly [brand]: B };

// --- Aggregate identity (numeric surrogate keys, PRD §9) ---

export type UserId = Brand<number, 'UserId'>;
export type VehicleId = Brand<number, 'VehicleId'>;
export type VehicleClassId = Brand<number, 'VehicleClassId'>;
export type ChassisLayoutId = Brand<number, 'ChassisLayoutId'>;
export type DocumentTypeId = Brand<number, 'DocumentTypeId'>;
export type VehicleDocumentId = Brand<number, 'VehicleDocumentId'>;
export type WorkOrderId = Brand<number, 'WorkOrderId'>;
export type AssignmentId = Brand<number, 'AssignmentId'>;
export type AssignmentModuleId = Brand<number, 'AssignmentModuleId'>;
export type WoPresetId = Brand<number, 'WoPresetId'>;
export type ChangeRequestId = Brand<number, 'ChangeRequestId'>;
export type ApprovalId = Brand<number, 'ApprovalId'>;
export type PartId = Brand<number, 'PartId'>;
export type GoodsReceiptId = Brand<number, 'GoodsReceiptId'>;
export type GoodsIssueId = Brand<number, 'GoodsIssueId'>;
export type StockAdjustmentId = Brand<number, 'StockAdjustmentId'>;
export type TyreId = Brand<number, 'TyreId'>;
export type TyreStatusId = Brand<number, 'TyreStatusId'>;
export type TyreReceiptId = Brand<number, 'TyreReceiptId'>;
export type RetreadOrderId = Brand<number, 'RetreadOrderId'>;
export type TyreCountId = Brand<number, 'TyreCountId'>;
export type PartPositionId = Brand<number, 'PartPositionId'>;
export type PartPlacementId = Brand<number, 'PartPlacementId'>;
export type MaintenanceAlertId = Brand<number, 'MaintenanceAlertId'>;
export type ScheduleCardId = Brand<number, 'ScheduleCardId'>;
export type NotificationId = Brand<number, 'NotificationId'>;
export type CustomerId = Brand<number, 'CustomerId'>;
export type InvoiceId = Brand<number, 'InvoiceId'>;
export type AuditLogId = Brand<number, 'AuditLogId'>;

/**
 * Mapping of every branded ID type to its brand tag, so a single generic
 * `toId` constructor stays type-safe without a per-type factory.
 */
interface IdBrandMap {
  UserId: UserId;
  VehicleId: VehicleId;
  VehicleClassId: VehicleClassId;
  ChassisLayoutId: ChassisLayoutId;
  DocumentTypeId: DocumentTypeId;
  VehicleDocumentId: VehicleDocumentId;
  WorkOrderId: WorkOrderId;
  AssignmentId: AssignmentId;
  AssignmentModuleId: AssignmentModuleId;
  WoPresetId: WoPresetId;
  ChangeRequestId: ChangeRequestId;
  ApprovalId: ApprovalId;
  PartId: PartId;
  GoodsReceiptId: GoodsReceiptId;
  GoodsIssueId: GoodsIssueId;
  StockAdjustmentId: StockAdjustmentId;
  TyreId: TyreId;
  TyreStatusId: TyreStatusId;
  TyreReceiptId: TyreReceiptId;
  RetreadOrderId: RetreadOrderId;
  TyreCountId: TyreCountId;
  PartPositionId: PartPositionId;
  PartPlacementId: PartPlacementId;
  MaintenanceAlertId: MaintenanceAlertId;
  ScheduleCardId: ScheduleCardId;
  NotificationId: NotificationId;
  CustomerId: CustomerId;
  InvoiceId: InvoiceId;
  AuditLogId: AuditLogId;
}

/**
 * Construct a branded ID from a raw database `number`.
 *
 * The brand tag is supplied as a type argument so the call site declares
 * intent: `toId<'WorkOrderId'>(row.id)`. This is the single sanctioned place
 * where a raw number crosses into the branded world; business logic should
 * never cast with `as`.
 */
export function toId<K extends keyof IdBrandMap>(value: number): IdBrandMap[K] {
  return value as IdBrandMap[K];
}

/** Read the underlying numeric value of any branded ID. */
export function idValue(id: Brand<number, string>): number {
  return id as unknown as number;
}
